entries[21082] = { ["name"] = "Siegel des Kreuzfahrers", ["text"] = "25 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit dem Geist eines Kreuzfahrers und verleiht 41 Nahkampfangriffskraft. Außerdem greift der Paladin um 40% schneller an, verursacht jedoch bei jedem Angriff weniger Schaden. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels richtet einen Feind 20 Sek. lang und erhöht den erlittenen Heiligschaden um bis zu 23. Eure Nahkampfangriffe frischen die Dauer dieses Siegels auf. Es kann immer nur jeweils ein Richturteil pro Paladin aktiv sein." }
entries[21084] = { ["name"] = "Siegel der Rechtschaffenheit", ["text"] = "20 Mana\nSofort\nErfüllt den Paladin 30 Sek. lang mit heiligem Geist, der jedem Nahkampfangriff zusätzlichen Heiligschaden in Höhe von [1.2 * ( 216 * 1.2 * 1.03 * Haupthandwaffen-Max-Grundgeschwindigkeit / 100) + 0.03 * (Haupthandwaffen-Max-Schaden + Haupthandwaffen-Min-Schaden) / 2 + 1] verleiht. Es kann immer nur jeweils ein Siegel auf dem Paladin aktiv sein.\n\nDie Entfesselung der Energie dieses Siegels fügt einem Feind 26 Heiligschaden zu." }
