entries[22568] = { ["name"] = "Wilder Biss", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der Schaden pro Combopunkt verursacht und jeden Extrapunkt Energie in 1 zusätzlichen Schaden umwandelt. Schaden wird durch Angriffskraft erhöht.\n1 Punkt: 50-66 Schaden\n2 Punkte: 86-102 Schaden\n3 Punkte: 122-138 Schaden\n4 Punkte: 158-174 Schaden\n5 Punkte: 194-210 Schaden" }
entries[22570] = { ["name"] = "Zerfleddern", ["text"] = "35 Energie Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Katzengestalt\nFinishing-Move der erhöhten Schaden verursacht und den Gegner handlungsunfähig macht. Jeglicher direkt zugefügter Schaden lässt das Ziel wieder zu sich kommen. Verursacht mehr Schaden und hält länger an, pro Combopunkt:\n1 Punkt: (84 + 45 + Haupthandwaffen-Min-Schaden)-(84 + 45 + Haupthandwaffen-Max-Schaden) Schaden und 2 Sekunden\n2 Punkte: (84 * 2 + 45 + Haupthandwaffen-Min-Schaden)-(84 * 2 + 45 + Haupthandwaffen-Max-Schaden) Schaden und 3 Sekunden\n3 Punkte: (84 * 3 + 45 + Haupthandwaffen-Min-Schaden)-(84 * 3 + 45 + Haupthandwaffen-Max-Schaden) Schaden und 4 Sekunden\n4 Punkte: (84 * 4 + 45 + Haupthandwaffen-Min-Schaden)-(84 * 4 + 45 + Haupthandwaffen-Max-Schaden) Schaden und 5 Sekunden\n5 Punkte: (84 * 5 + 45 + Haupthandwaffen-Min-Schaden)-(84 * 5 + 45 + Haupthandwaffen-Max-Schaden) Schaden und 6 Sekunden" }
